//! The [`ensemble`] macro, which turns the component modules of a Rust file generated by Clean into a witness generation [`crate::witness_generation::Program`] and a [`crate::GeneratedAirSpec`].

/// Implements an extracted ensemble on top of its generated modules.
///
/// Every module listed in `components`, and the module `verifier`, must be in scope. Component modules provide the constants `NAME`, `INPUT_WIDTH`, `WIDTH`, `FIXED_WIDTH`, `FIXED_HEIGHT` and `INTERACTIONS`, and the functions `fixed_row`, `complete`, `constraints`, `interactions`, `mode`, `initial_row` and `padding`. The verifier module provides `INTERACTIONS` and `interactions`.
///
/// The macro defines the type `Ensemble`, implementing both traits, the AIR statement `Statement<F>`, and `generate`, the witness generator.
#[macro_export]
macro_rules! ensemble {
    (
        field_order: $field_order:expr,
        fuel: $fuel:expr,
        public_inputs: $public_inputs:expr,
        prover_inputs: $prover_inputs:expr,
        hint_tables: [$($hint_table:expr),* $(,)?],
        components: [$($component:ident),+ $(,)?] $(,)?
    ) => {
        /// The extracted ensemble: its witness generation program and its AIR.
        #[derive(Clone, Copy, Debug)]
        pub struct Ensemble;

        impl<F: $crate::witness_generation::WitnessField> $crate::witness_generation::Program<F>
            for Ensemble
        {
            const FIELD_ORDER: u64 = $field_order;
            const FUEL: usize = $fuel;
            const COMPONENTS: usize = [$($component::NAME),+].len();
            const PUBLIC_INPUTS: usize = $public_inputs;
            const PROVER_INPUTS: usize = $prover_inputs;
            const HINT_TABLES: &'static [$crate::witness_generation::HintTable] = &[$($hint_table),*];
            const FIXED_WIDTHS: &'static [usize] = &[$($component::FIXED_WIDTH),+];
            const COMPONENT_NAMES: &'static [&'static str] = &[$($component::NAME),+];

            fn modes() -> $crate::__private::Vec<$crate::witness_generation::Mode<F>> {
                $crate::__private::vec![$($component::mode::<F>()),+]
            }

            fn padding() -> $crate::__private::Vec<$crate::witness_generation::Padding<F>> {
                $crate::__private::vec![$($component::padding::<F>()),+]
            }

            fn initial_row(
                component: usize,
                row: u64,
                hint: &$crate::witness_generation::WitnessData<F>,
            ) -> $crate::__private::Vec<F> {
                let initial_rows: &[fn(
                    u64,
                    &$crate::witness_generation::WitnessData<F>,
                ) -> $crate::__private::Vec<F>] = &[$($component::initial_row::<F>),+];
                initial_rows[component](row, hint)
            }

            fn complete_row(
                component: usize,
                input: &[F],
                data: &$crate::witness_generation::WitnessData<F>,
                hint: &$crate::witness_generation::WitnessData<F>,
            ) -> Result<$crate::__private::Vec<F>, $crate::__private::String> {
                let completes: &[fn(
                    &mut $crate::__private::Vec<F>,
                    &$crate::witness_generation::WitnessData<F>,
                    &$crate::witness_generation::WitnessData<F>,
                )] = &[$($component::complete::<F>),+];
                let input_widths: &[usize] = &[$($component::INPUT_WIDTH),+];
                let widths: &[usize] = &[$($component::WIDTH),+];
                let Some(complete) = completes.get(component) else {
                    return Err($crate::__private::format!(
                        "component index {component} is out of bounds"
                    ));
                };
                if input.len() != input_widths[component] {
                    return Err($crate::__private::format!(
                        "component input has width {}, expected {}",
                        input.len(),
                        input_widths[component]
                    ));
                }
                let mut row = input.to_vec();
                complete(&mut row, data, hint);
                if row.len() != widths[component] {
                    return Err($crate::__private::format!(
                        "generated row has width {}, expected {}",
                        row.len(),
                        widths[component]
                    ));
                }
                Ok(row)
            }

            fn interactions(
                component: usize,
                row: &[F],
            ) -> $crate::__private::Vec<$crate::witness_generation::Interaction<F>> {
                <Ensemble as $crate::GeneratedAirSpec>::interactions(component, row)
            }

            fn verifier_interactions(
                public_input: &[F],
            ) -> $crate::__private::Vec<$crate::witness_generation::Interaction<F>> {
                verifier::interactions(public_input)
            }
        }

        impl $crate::GeneratedAirSpec for Ensemble {
            const FIELD_ORDER: u64 = $field_order;
            const PUBLIC_VALUES: usize = $public_inputs;
            const WIDTHS: &'static [usize] = &[$($component::WIDTH - $component::FIXED_WIDTH),+];
            const FIXED_WIDTHS: &'static [usize] = &[$($component::FIXED_WIDTH),+];
            const FIXED_HEIGHTS: &'static [usize] = &[$($component::FIXED_HEIGHT),+];
            const INTERACTIONS_PER_ROW: &'static [usize] = &[$($component::INTERACTIONS),+];
            const VERIFIER_INTERACTIONS: usize = verifier::INTERACTIONS;

            fn fixed_row<F: $crate::witness_generation::WitnessField>(
                component: usize,
                row: u64,
            ) -> $crate::__private::Vec<F> {
                let fixed_rows: &[fn(u64) -> $crate::__private::Vec<F>] =
                    &[$($component::fixed_row::<F>),+];
                fixed_rows[component](row)
            }

            fn constraints<E: $crate::__private::PrimeCharacteristicRing + Clone>(
                component: usize,
                row: &[E],
            ) -> $crate::__private::Vec<E> {
                let constraints: &[fn(&[E]) -> $crate::__private::Vec<E>] =
                    &[$($component::constraints::<E>),+];
                constraints[component](row)
            }

            fn interactions<E: $crate::__private::PrimeCharacteristicRing + Clone>(
                component: usize,
                row: &[E],
            ) -> $crate::__private::Vec<$crate::witness_generation::Interaction<E>> {
                let interactions: &[fn(
                    &[E],
                ) -> $crate::__private::Vec<$crate::witness_generation::Interaction<E>>] =
                    &[$($component::interactions::<E>),+];
                interactions
                    .get(component)
                    .map_or_else($crate::__private::Vec::new, |interactions| interactions(row))
            }

            fn verifier_interactions<F: $crate::witness_generation::WitnessField>(
                public_values: &[F],
            ) -> $crate::__private::Vec<$crate::witness_generation::Interaction<F>> {
                verifier::interactions(public_values)
            }
        }

        /// The AIR statement of the extracted ensemble.
        pub type Statement<F> = $crate::GeneratedEnsemble<F, Ensemble>;

        /// Generate a witness of the extracted ensemble.
        pub fn generate<F: $crate::witness_generation::WitnessField>(
            public_input: &[F],
            prover_input: &[F],
        ) -> Result<
            $crate::witness_generation::EnsembleWitness<F>,
            $crate::witness_generation::WitnessGenerationError,
        > {
            $crate::witness_generation::generate::<F, Ensemble>(public_input, prover_input)
        }
    };
}
